    "source": "\"\"\"Number theory toolkit. Preconditions: gcd/ex_gcd take a, b >= 0; pow_mod takes base >= 0, power >= 0, m >= 1; inv_mod takes any a, m >= 1.\"\"\"\n\n\ndef gcd(a: int, b: int) -> int:\n    \"\"\"Euclid: gcd(a, 0) = a.\"\"\"\n    while b != 0:\n        a, b = b, a % b\n    return a\n\n\ndef ex_gcd(a: int, b: int) -> list[int]:\n    \"\"\"Extended Euclid: returns [g, x, y] with a*x + b*y = g = gcd(a, b).\"\"\"\n    r0, r1, s0, s1, t0, t1 = a, b, 1, 0, 0, 1\n    while r1 != 0:\n        q = r0 // r1\n        r0, r1 = r1, r0 - q * r1\n        s0, s1 = s1, s0 - q * s1\n        t0, t1 = t1, t0 - q * t1\n    return [r0, s0, t0]\n\n\ndef pow_mod(base: int, power: int, m: int) -> int:\n    \"\"\"Fast power: base**power mod m by scanning the bits of power.\"\"\"\n    result = 1 % m\n    base %= m\n    while power > 0:\n        if power & 1:\n            result = result * base % m\n        base = base * base % m\n        power >>= 1\n    return result\n\n\ndef inv_mod(a: int, m: int) -> int:\n    \"\"\"Modular inverse of a mod m via ex_gcd; -1 when gcd(a, m) != 1 (no inverse exists).\"\"\"\n    g, x, _ = ex_gcd(a % m, m)\n    if g != 1:\n        return -1\n    return x % m\n\n\ndef sieve(n: int) -> list[int]:\n    \"\"\"Sieve of Eratosthenes: all primes <= n in increasing order.\"\"\"\n    composite = [False] * (n + 1)\n    primes: list[int] = []\n    for i in range(2, n + 1):\n        if composite[i]:\n            continue\n        primes.append(i)\n        for j in range(i * i, n + 1, i):\n            composite[j] = True\n    return primes\n",
