    "documentId": "number-theory.java",
    "language": "java",
    "title": "数论工具箱 gcd / exgcd / 快速幂 / 逆元 / 筛法（教学版） (Java)",
    "sourceFile": "src/codeCatalog/number_theory/langs/NumberTheory.java",
    "source": "/** Number theory toolkit. Preconditions: gcd/exGcd take a, b >= 0; powMod takes base >= 0, power >= 0, m >= 1; invMod takes any a, m >= 1. */\npublic class NumberTheory {\n    /** Euclid: gcd(a, 0) = a. */\n    static long gcd(long a, long b) {\n        while (b != 0) { long t = a % b; a = b; b = t; }\n        return a;\n    }\n\n    /** Extended Euclid: returns [g, x, y] with a*x + b*y = g = gcd(a, b). */\n    static long[] exGcd(long a, long b) {\n        long r0 = a, r1 = b, s0 = 1, s1 = 0, t0 = 0, t1 = 1;\n        while (r1 != 0) {\n            long q = r0 / r1, t;\n            t = r0 - q * r1; r0 = r1; r1 = t;\n            t = s0 - q * s1; s0 = s1; s1 = t;\n            t = t0 - q * t1; t0 = t1; t1 = t;\n        }\n        return new long[] {r0, s0, t0};\n    }\n\n    /** Fast power: base^power mod m by scanning the bits of power. */\n    static long powMod(long base, long power, long m) {\n        long result = 1 % m;\n        base %= m;\n        while (power > 0) {\n            if ((power & 1) == 1) result = result * base % m;\n            base = base * base % m;\n            power >>= 1;\n        }\n        return result;\n    }\n\n    /** Modular inverse of a mod m via exGcd; -1 when gcd(a, m) != 1 (no inverse exists). */\n    static long invMod(long a, long m) {\n        long[] e = exGcd(((a % m) + m) % m, m);\n        if (e[0] != 1) return -1;\n        return ((e[1] % m) + m) % m;\n    }\n\n    /** Sieve of Eratosthenes: all primes <= n in increasing order. */\n    static long[] sieve(long nn) {\n        int n = (int) nn;\n        boolean[] composite = new boolean[n + 1];\n        long[] primes = new long[n + 1];\n        int cnt = 0;\n        for (int i = 2; i <= n; i++) {\n            if (composite[i]) continue;\n            primes[cnt++] = i;\n            for (long j = (long) i * i; j <= n; j += i) composite[(int) j] = true;\n        }\n        return java.util.Arrays.copyOf(primes, cnt);\n    }\n}\n",
