    "title": "数论工具箱 gcd / exgcd / 快速幂 / 逆元 / 筛法（教学版） (Rust)",
    "sourceFile": "src/codeCatalog/number_theory/langs/number_theory.rs",
    "source": "// Number theory toolkit. Preconditions: gcd/ex_gcd take a, b >= 0; pow_mod takes base >= 0, power >= 0, m >= 1; inv_mod takes any a, m >= 1.\n\n/// Euclid: gcd(a, 0) = a.\npub fn gcd(mut a: i64, mut b: i64) -> i64 {\n    while b != 0 { let t = a % b; a = b; b = t; }\n    a\n}\n\n/// Extended Euclid: returns [g, x, y] with a*x + b*y = g = gcd(a, b).\npub fn ex_gcd(a: i64, b: i64) -> [i64; 3] {\n    let (mut r0, mut r1, mut s0, mut s1, mut t0, mut t1) = (a, b, 1i64, 0i64, 0i64, 1i64);\n    while r1 != 0 {\n        let q = r0 / r1;\n        (r0, r1) = (r1, r0 - q * r1);\n        (s0, s1) = (s1, s0 - q * s1);\n        (t0, t1) = (t1, t0 - q * t1);\n    }\n    [r0, s0, t0]\n}\n\n/// Fast power: base^power mod m by scanning the bits of power.\npub fn pow_mod(mut base: i64, mut power: i64, m: i64) -> i64 {\n    let mut result = 1 % m;\n    base %= m;\n    while power > 0 {\n        if power & 1 == 1 { result = result * base % m; }\n        base = base * base % m;\n        power >>= 1;\n    }\n    result\n}\n\n/// Modular inverse of a mod m via ex_gcd; -1 when gcd(a, m) != 1 (no inverse exists).\npub fn inv_mod(a: i64, m: i64) -> i64 {\n    let e = ex_gcd(((a % m) + m) % m, m);\n    if e[0] != 1 { return -1; }\n    ((e[1] % m) + m) % m\n}\n\n/// Sieve of Eratosthenes: all primes <= n in increasing order.\npub fn sieve(n: i64) -> Vec<i64> {\n    let n = n as usize;\n    let mut composite = vec![false; n + 1];\n    let mut primes: Vec<i64> = Vec::new();\n    for i in 2..=n {\n        if composite[i] { continue; }\n        primes.push(i as i64);\n        let mut j = i * i;\n        while j <= n { composite[j] = true; j += i; }\n    }\n    primes\n}\n",
