    "documentId": "number-theory.go",
    "language": "go",
    "title": "数论工具箱 gcd / exgcd / 快速幂 / 逆元 / 筛法（教学版） (Go)",
    "sourceFile": "src/codeCatalog/number_theory/langs/number_theory.go",
    "source": "package main\n\n// Number theory toolkit. Preconditions: Gcd/ExGcd take a, b >= 0; PowMod takes base >= 0, power >= 0, m >= 1; InvMod takes any a, m >= 1.\n\n// Gcd is Euclid: gcd(a, 0) = a.\nfunc Gcd(a, b int64) int64 {\n\tfor b != 0 { a, b = b, a%b }\n\treturn a\n}\n\n// ExGcd is extended Euclid: returns [g, x, y] with a*x + b*y = g = gcd(a, b).\nfunc ExGcd(a, b int64) []int64 {\n\tr0, r1, s0, s1, t0, t1 := a, b, int64(1), int64(0), int64(0), int64(1)\n\tfor r1 != 0 {\n\t\tq := r0 / r1\n\t\tr0, r1 = r1, r0-q*r1\n\t\ts0, s1 = s1, s0-q*s1\n\t\tt0, t1 = t1, t0-q*t1\n\t}\n\treturn []int64{r0, s0, t0}\n}\n\n// PowMod is fast power: base^power mod m by scanning the bits of power.\nfunc PowMod(base, power, m int64) int64 {\n\tresult := 1 % m\n\tbase %= m\n\tfor power > 0 {\n\t\tif power&1 == 1 { result = result * base % m }\n\t\tbase = base * base % m\n\t\tpower >>= 1\n\t}\n\treturn result\n}\n\n// InvMod is the modular inverse of a mod m via ExGcd; -1 when gcd(a, m) != 1 (no inverse exists).\nfunc InvMod(a, m int64) int64 {\n\te := ExGcd(((a%m)+m)%m, m)\n\tif e[0] != 1 { return -1 }\n\treturn ((e[1] % m) + m) % m\n}\n\n// Sieve is the sieve of Eratosthenes: all primes <= n in increasing order.\nfunc Sieve(n int64) []int64 {\n\tcomposite := make([]bool, n+1)\n\tprimes := []int64{}\n\tfor i := int64(2); i <= n; i++ {\n\t\tif composite[i] { continue }\n\t\tprimes = append(primes, i)\n\t\tfor j := i * i; j <= n; j += i { composite[j] = true }\n\t}\n\treturn primes\n}\n",
